import { asset_config_create_list_update_locations } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
import SnackBar from "@/components/SnackBar.vue";
import { get_Org_details } from "@/mixins/GetOrgDetails.js";
import { get_all_org_users } from "@/mixins/GetUsersDropdown.js";
// import { EventBus } from "@/EventBus";

export default {
  components: {
    SnackBar
  },
  emits: ['backAction'],
  mixins: [get_Org_details, get_all_org_users],
  data() {
    return {
      locationSettting: "",
      selectedMember: "",
      userList: [],
      search: "",
      loading: false,
      SnackBarComponent: {},
      toggle_exclusive: "NO",
      verificationFrequency: 3,
      assetsDeployemnt: null,
      assetTagsSettings: "no"

      // internalOrganization: false,
      // asstesExternalDeploy: false,
    };
  },
  async created() {
    // await this.get_Org_details();
    // await this.get_all_org_users();
    // await this.fetch_users();
    var data = this.$store.getters.GetOrgDetails;
    this.verificationFrequency = data.organization.asset_verification_frequency != undefined ? data.organization.asset_verification_frequency : 3;
    this.locationSettting = data.organization.is_asset_location_configured == false ? "defaultLocation" : "customLocation";
    this.assetsDeployemnt = data.organization.is_asset_deployed_external == true ? "asstesExternalDeploy" : "internalOrganization";
    this.assetTagsSettings = data.organization.enable_asset_tags == false ? "no" : "yes";
    // var asset_approval =
    //   this.orgDetails.organization.asset_management_settings != undefined
    //     ? this.orgDetails.organization.asset_management_settings
    //     : {};
    // if (this.orgDetails.organization.asset_management_settings != undefined) {
    //   this.selectedMember =
    //     asset_approval.is_approval == true
    //       ? asset_approval.approvers_list[0].user_email_id
    //       : "";
    // }
    // this.toggle_exclusive = asset_approval.is_approval == true ? "YES" : "NO";
  },
  methods: {
    cleardata() {
      this.selectedMember = "";
    },
    createApprovalObject(isApproval, memberEmail) {
      const baseObject = {
        name: "RETIRE_ASSET",
        approvers_list: [],
        is_approval: true
      };
      // isApproval == "YES" ? true : false,

      if (isApproval && memberEmail && memberEmail.trim() !== "") {
        baseObject.approvers_list.push({
          step_no: 1,
          user_email_id: memberEmail
        });
      }
      return JSON.stringify(baseObject);
    },
    fetch_data() {
      const baseObject = {
        name: "RETIRE_ASSET",
        approvers_list: [],
        is_approval: false
      };
      return JSON.stringify(baseObject);
    },
    fetch_users() {
      this.userList = [];
      this.orgUsers.forEach(element => {
        if (element.user_status == "ACTIVE" && element.user_type != "CHATBOT") {
          this.userList.push({
            title: element.full_user_name,
            value: element.user_email_id
          });
        }
      });
      this.userList.sort((a, b) => a.label.localeCompare(b.label));
    },
    async save_action() {
      if (this.$refs.form.validate()) {
        this.loading = true;
        var data = this.$store.getters.GetUserObj;
        try {
          let result = await API.graphql(graphqlOperation(asset_config_create_list_update_locations, {
            input: {
              action_type: "CONFIGURE",
              is_asset_location_configured: this.locationSettting == "defaultLocation" ? false : true,
              organization_id: data.organization.organization_id,
              asset_verification_frequency: parseInt(this.verificationFrequency),
              asset_management_settings: this.selectedMember != null || this.selectedMember != "" ? this.createApprovalObject(this.toggle_exclusive, this.selectedMember) : this.fetch_data(),
              enable_asset_tags: this.assetTagsSettings == "yes" ? true : false
            }
          }));
          var response = JSON.parse(result.data.asset_config_create_list_update_locations);
          if (response.Status == "SUCCESS") {
            await this.get_Org_details();
            this.SnackBarComponent = {
              SnackbarVmodel: true,
              SnackbarColor: "green",
              SnackbarText: response.Message,
              timeout: 5000,
              Top: true
            };
            this.loading = false;
            this.$store.commit("SetOrgDetails", this.orgDetails);
            this.locationSettting = this.orgDetails.organization.is_asset_location_configured == false ? "defaultLocation" : "customLocation";
            var data = {
              location: this.locationSettting,
              tagSetiing: this.assetTagsSettings
            };
            // EventBus.$emit("locationsetting", data);
            // EventBus.$emit("", this.locationSettting);
          } else {
            this.loading = false;
          }
        } catch (error) {
          this.loading = false;
        }
      }
    }
  }
};
